// Vitest runs the unit tests next to the domain code: domain/slots.test.ts and the others.
// Run them from this folder: bunx vitest run
import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    include: ["domain/**/*.test.ts"],
  },
});
// Basket rules: BASK-1 to BASK-9 in world/requirements/basket.md.
// This is the fixed build of world/domain/basket.ts, with the planted bugs taken out.

export type Product = {
  sku: string;
  name: string;
  category: string;
  unit: "each" | "kg";
  priceCents: number;
  allergens: string[];
  stock: number;
  chilled: boolean;
  offer?: "3for2";
};
// A line holds a count for "each" items and grams for "kg" items.
export type Line = { sku: string; qty: number; grams: number; substitutes: boolean };
export type PricedLine = Line & {
  name: string;
  unit: Product["unit"];
  totalCents: number;
  offerCents: number;
  outOfStock: boolean;
};
export type Totals = {
  lines: PricedLine[];
  subtotalCents: number;
  offerCents: number;
  voucherCents: number;
  deliveryCents: number;
  totalCents: number;
  afterDiscountCents: number;
};

export const WEIGHT_STEP_GRAMS = 250;
export const MAX_QTY = 20;

// BASK-4: loose produce costs weight times price per kg, rounded once to the cent.
export function lineTotal(product: Product, line: Line): number {
  if (product.unit !== "kg") {
    return line.qty * product.priceCents;
  }
  return Math.round((line.grams * product.priceCents) / 1000);
}

// BASK-6: 3 for 2. Every third unit of the same product is free.
export function offerDiscount(product: Product, line: Line): number {
  const hasThreeForTwo = product.offer === "3for2" && product.unit === "each";
  if (!hasThreeForTwo) {
    return 0;
  }
  const freeUnits = Math.floor(line.qty / 3);
  return freeUnits * product.priceCents;
}

// Every line comes from a product in the shop, so a missing one is a programming mistake.
function productFor(products: Map<string, Product>, sku: string): Product {
  const product = products.get(sku);
  if (!product) {
    throw new Error(`No product with sku ${sku}.`);
  }
  return product;
}

function priceLine(line: Line, products: Map<string, Product>): PricedLine {
  const product = productFor(products, line.sku);
  return {
    ...line,
    name: product.name,
    unit: product.unit,
    totalCents: lineTotal(product, line),
    offerCents: offerDiscount(product, line),
    outOfStock: product.stock <= 0,
  };
}

function sumOf(numbers: number[]): number {
  let total = 0;
  for (const amount of numbers) {
    total += amount;
  }
  return total;
}

// BASK-7: the voucher never applies to a line with a multi-buy offer.
function voucherBaseCents(priced: PricedLine[], products: Map<string, Product>): number {
  const linesWithoutOffer = priced.filter((line) => !productFor(products, line.sku).offer);
  return sumOf(linesWithoutOffer.map((line) => line.totalCents));
}

export function priceBasket(
  lines: Line[],
  products: Map<string, Product>,
  opts: { voucherPercent: number; deliveryCents: number },
): Totals {
  const priced = lines.map((line) => priceLine(line, products));
  const subtotalCents = sumOf(priced.map((line) => line.totalCents));
  const offerCents = sumOf(priced.map((line) => line.offerCents));
  const voucherBase = voucherBaseCents(priced, products);
  const voucherCents = Math.round((voucherBase * opts.voucherPercent) / 100);
  const afterDiscountCents = subtotalCents - offerCents - voucherCents;
  return {
    lines: priced,
    subtotalCents,
    offerCents,
    voucherCents,
    deliveryCents: opts.deliveryCents,
    afterDiscountCents,
    totalCents: afterDiscountCents + opts.deliveryCents,
  };
}

// BASK-8: checkout needs at least the minimum after discounts.
export function meetsMinimum(afterDiscountCents: number, minimumCents: number): boolean {
  return afterDiscountCents >= minimumCents;
}

function lineFor(lines: Line[], product: Product): Line | undefined {
  return lines.find((line) => line.sku === product.sku);
}

// BASK-1: adding an item that is already in the basket raises its quantity.
export function addToLines(lines: Line[], product: Product, amount: number): Line[] {
  const existing = lineFor(lines, product);
  const soldByWeight = product.unit === "kg";
  if (existing) {
    if (soldByWeight) {
      existing.grams += amount;
    } else {
      existing.qty = Math.min(MAX_QTY, existing.qty + amount);
    }
    return lines;
  }
  const newLine: Line = {
    sku: product.sku,
    qty: soldByWeight ? 1 : amount,
    grams: soldByWeight ? amount : 0,
    substitutes: true,
  };
  return [...lines, newLine];
}

// BASK-3: removing the last unit removes the line.
export function removeOne(lines: Line[], product: Product): Line[] {
  const line = lineFor(lines, product);
  if (!line) {
    return lines;
  }
  let empty: boolean;
  if (product.unit === "kg") {
    line.grams -= WEIGHT_STEP_GRAMS;
    empty = line.grams <= 0;
  } else {
    line.qty -= 1;
    empty = line.qty <= 0;
  }
  if (!empty) {
    return lines;
  }
  return lines.filter((otherLine) => otherLine !== line);
}

// The quantity box. No written rule covers a negative number.
export function setQuantity(lines: Line[], product: Product, qty: number): Line[] {
  if (!Number.isInteger(qty)) {
    throw new RangeError("Quantity must be a whole number.");
  }
  const outOfRange = qty < 1 || qty > MAX_QTY;
  if (outOfRange) {
    throw new RangeError(`Quantity must be from 1 to ${MAX_QTY}.`);
  }
  const line = lineFor(lines, product);
  if (!line) {
    return lines;
  }
  if (product.unit === "kg") {
    line.grams = qty * WEIGHT_STEP_GRAMS;
  } else {
    line.qty = qty;
  }
  return lines;
}
// Store time. The world runs on a store clock that tests can set, so slot rules are repeatable.
export type LocalParts = { date: string; hour: number; minute: number };

export function localParts(instant: Date, timeZone: string): LocalParts {
  const formatter = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  });
  const pieces = formatter.formatToParts(instant);
  const part = Object.fromEntries(pieces.map((piece) => [piece.type, piece.value]));
  return {
    date: `${part.year}-${part.month}-${part.day}`,
    hour: Number(part.hour),
    minute: Number(part.minute),
  };
}

export function addDays(date: string, days: number): string {
  // Noon UTC keeps the date the same in every time zone while we move it.
  const moment = new Date(`${date}T12:00:00Z`);
  moment.setUTCDate(moment.getUTCDate() + days);
  return moment.toISOString().slice(0, 10);
}

export function dateLabel(date: string): string {
  const moment = new Date(`${date}T12:00:00Z`);
  return moment.toLocaleDateString("en-US", {
    weekday: "short",
    day: "numeric",
    month: "short",
    timeZone: "UTC",
  });
}
// Delivery slots: SLOT-1 to SLOT-8 in world/requirements/slots.md.
// This is the fixed build of world/domain/slots.ts, with the planted bugs taken out.
import { addDays, dateLabel, localParts } from "./clock";

export type SlotStatus = "open" | "full" | "closed";
export type Slot = {
  slotId: string; // 2026-03-11T08
  date: string;
  start: string; // 08:00
  end: string; // 09:00
  dateText: string; // Wed, Mar 11
  label: string; // Wed, Mar 11, 08:00 to 09:00
  feeCents: number;
  capacity: number;
  booked: number;
  remaining: number;
  status: SlotStatus;
};

export const FIRST_HOUR = 8;
export const LAST_HOUR = 19; // the last slot starts 19:00 and ends 20:00
export const CUTOFF_HOUR = 22;
export const DATES_SHOWN = 3;

// SLOT-5: 17:00 and 18:00 starts are peak.
export function slotFee(hour: number): number {
  return hour === 17 || hour === 18 ? 499 : 299;
}

// SLOT-3: next-date slots close at 22:00 store time the evening before.
export function cutoffPassed(now: Date, timeZone: string): boolean {
  const hour = localParts(now, timeZone).hour;
  return hour >= CUTOFF_HOUR;
}

// SLOT-2: a slot takes at most `capacity` orders.
export function isFull(booked: number, capacity: number): boolean {
  return booked >= capacity;
}

// Turns 8 into "08", so every hour has two digits.
const twoDigits = (hour: number) => String(hour).padStart(2, "0");

function slotStatus(isFirstDate: boolean, closedFirst: boolean, full: boolean): SlotStatus {
  if (isFirstDate && closedFirst) {
    return "closed";
  }
  if (full) {
    return "full";
  }
  return "open";
}

type SlotPlace = { date: string; hour: number; bookedCount: number; capacity: number };

function makeSlot(place: SlotPlace, status: SlotStatus): Slot {
  const { date, hour, bookedCount, capacity } = place;
  const start = `${twoDigits(hour)}:00`;
  const end = `${twoDigits(hour + 1)}:00`;
  const dateText = dateLabel(date);
  return {
    slotId: `${date}T${twoDigits(hour)}`,
    date,
    start,
    end,
    dateText,
    label: `${dateText}, ${start} to ${end}`,
    feeCents: slotFee(hour),
    capacity,
    booked: bookedCount,
    remaining: Math.max(0, capacity - bookedCount),
    status,
  };
}

export function listSlots(
  now: Date,
  timeZone: string,
  booked: Record<string, number>,
  capacity: number,
): Slot[] {
  const today = localParts(now, timeZone).date;
  const closedFirst = cutoffPassed(now, timeZone);
  const slots: Slot[] = [];
  for (let dayNumber = 1; dayNumber <= DATES_SHOWN; dayNumber++) {
    const date = addDays(today, dayNumber);
    for (let hour = FIRST_HOUR; hour <= LAST_HOUR; hour++) {
      const bookedCount = booked[`${date}T${twoDigits(hour)}`] ?? 0;
      const full = isFull(bookedCount, capacity);
      const status = slotStatus(dayNumber === 1, closedFirst, full);
      slots.push(makeSlot({ date, hour, bookedCount, capacity }, status));
    }
  }
  return slots;
}

export function parseSlotId(id: string): { date: string; hour: number } | null {
  const match = /^(\d{4}-\d{2}-\d{2})T(\d{2})$/.exec(id);
  if (!match) {
    return null;
  }
  const hour = Number(match[2]);
  if (hour < FIRST_HOUR || hour > LAST_HOUR) {
    return null;
  }
  return { date: match[1], hour };
}
// Substitutions at packing: SUB-1 to SUB-7 in world/requirements/substitutions.md.
// This is the fixed build of world/domain/substitutions.ts, with the planted bugs taken out.
import type { Line, Product } from "./basket";

export const PRICE_TOLERANCE = 0.15;

// SUB-5: a substitute costs at most 15% more than the item it replaces.
export function withinPrice(original: Product, candidate: Product): boolean {
  return candidate.priceCents <= Math.floor(original.priceCents * (1 + PRICE_TOLERANCE));
}

export function safeFor(candidate: Product, allergens: string[]): boolean {
  return !candidate.allergens.some((allergen) => allergens.includes(allergen));
}

// SUB-3, SUB-4, SUB-5, SUB-6: same category, no declared allergen, within price, in stock.
// The closest price wins.
function canReplace(original: Product, candidate: Product, allergens: string[]): boolean {
  return (
    candidate.sku !== original.sku &&
    candidate.category === original.category &&
    candidate.stock > 0 &&
    withinPrice(original, candidate) &&
    safeFor(candidate, allergens)
  );
}

export function pickSubstitute(
  original: Product,
  products: Product[],
  allergens: string[],
): Product | null {
  const suitable = products.filter((candidate) => canReplace(original, candidate, allergens));
  const priceGap = (candidate: Product) => Math.abs(candidate.priceCents - original.priceCents);
  // Equal price gaps are ordered by sku, so the choice is always the same.
  suitable.sort(
    (first, second) => priceGap(first) - priceGap(second) || first.sku.localeCompare(second.sku),
  );
  return suitable[0] ?? null;
}

export type Packed = {
  sku: string;
  status: "packed" | "substituted" | "unavailable";
  substituteSku?: string;
  substituteName?: string;
};

// SUB-2: "No substitutes" is always respected, chilled items included.
export function packLine(
  line: Line,
  product: Product,
  products: Product[],
  allergens: string[],
): Packed {
  if (product.stock > 0) {
    return { sku: line.sku, status: "packed" };
  }
  if (!line.substitutes) {
    return { sku: line.sku, status: "unavailable" };
  }
  const substitute = pickSubstitute(product, products, allergens);
  if (!substitute) {
    return { sku: line.sku, status: "unavailable" };
  }
  return {
    sku: line.sku,
    status: "substituted",
    substituteSku: substitute.sku,
    substituteName: substitute.name,
  };
}

