    expect(totals.totalCents).toBe(1005);
  });

  it("returns priced lines with name, unit and totals", () => {
    const totals = priceBasket([each("beans", 3)], shop, { voucherPercent: 0, deliveryCents: 0 });
    expect(totals.lines).toEqual([
      {
        sku: "beans",
        qty: 3,
        grams: 0,
        substitutes: true,
        name: "Baked beans",
        unit: "each",
        totalCents: 300,
        offerCents: 100,
        outOfStock: false,
